def normalize_tags(tags):
    seen = set()
    for tag in tags:
        key = tag.strip().casefold()
        if key not in seen:
            seen.add(key)
            yield tag

def most_common_word(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return max(counts, key=counts.get)

def intersection_labels(first, second):
    second_labels = set(second)
    seen = set()

    for label in first:
        if label in second_labels and label not in seen:
            seen.add(label)
            yield label

def common_suffix(words):
    if not words:
        return ""

    reversed_words = [word[::-1] for word in words]
    suffix = []

    for characters in zip(*reversed_words):
        if len(set(characters)) != 1:
            break
        suffix.append(characters[0])

    return "".join(reversed(suffix))

def parse_clock(text):
    time_part, period = text.strip().split()
    hour_text, minute_text = time_part.split(":")
    hour = int(hour_text)
    minute = int(minute_text)

    if not 1 <= hour <= 12 or len(minute_text) != 2 or not 0 <= minute <= 59:
        raise ValueError("Invalid clock value")
    if period not in ("AM", "PM"):
        raise ValueError("Invalid period")

    if period == "AM":
        hour %= 12
    else:
        hour = hour % 12 + 12

    return hour * 60 + minute

def sort_events(events):
    from datetime import datetime

    return sorted(
        events,
        key=lambda event: datetime.fromisoformat(
            event["time"].replace("Z", "+00:00")
        ),
    )

def matrix_multiply(left, right):
    return [
        [sum(a * b for a, b in zip(row, column)) for column in zip(*right)]
        for row in left
    ]

def count_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    islands = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] != 1 or visited[row][col]:
                continue

            islands += 1
            stack = [(row, col)]
            visited[row][col] = True

            while stack:
                current_row, current_col = stack.pop()

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    next_row = current_row + dr
                    next_col = current_col + dc

                    if (
                        0 <= next_row < rows
                        and 0 <= next_col < cols
                        and grid[next_row][next_col] == 1
                        and not visited[next_row][next_col]
                    ):
                        visited[next_row][next_col] = True
                        stack.append((next_row, next_col))

    return islands
